import { useState, useCallback, useId } from 'react';

export function useHeadlessAccordion(items: string[], allowMultiple = false) {
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const baseId = useId();

  const getHeaderId = (item: string) => `${baseId}-header-${item.replace(/\s+/g, '-')}`;
  const getPanelId = (item: string) => `${baseId}-panel-${item.replace(/\s+/g, '-')}`;

  const toggle = useCallback((item: string) => {
    setExpanded(prev => {
      const next = new Set(prev);
      if (next.has(item)) {
        next.delete(item);
      } else {
        if (!allowMultiple) next.clear();
        next.add(item);
      }
      return next;
    });
  }, [allowMultiple]);

  const isExpanded = useCallback((item: string) => expanded.has(item), [expanded]);

  const getHeaderProps = useCallback((item: string) => ({
    id: getHeaderId(item),
    'aria-expanded': expanded.has(item),
    'aria-controls': getPanelId(item),
    onClick: () => toggle(item),
  }), [expanded, toggle, baseId]);

  const getPanelProps = useCallback((item: string) => ({
    role: 'region' as const,
    id: getPanelId(item),
    'aria-labelledby': getHeaderId(item),
  }), [baseId]);

  return { getHeaderProps, getPanelProps, isExpanded, toggle };
}
